{
  "info": {
    "title": "UAE Insurance API",
    "description": "## UAE Open Finance Insurance API Specification",
    "version": "v2.2-rc2"
  },
  "servers": [
    {
      "url": "https://rs1.[LFICODE].apihub.openfinance.ae/open-finance/insurance/v2.1"
    },
    {
      "url": "https://rs1.[LFICODE].preprod.apihub.openfinance.ae/open-finance/insurance/v2.1"
    },
    {
      "url": "https://rs1.altareq1.sandbox.apihub.openfinance.ae/open-finance/insurance/v2.1"
    }
  ],
  "source_path": "/employment-insurance-policies",
  "operations": {
    "post": {
      "operationId": "EmploymentInsuranceCreatePolicy_signedRequest",
      "summary": "Create an employment insurance policy from a quote",
      "description": "Create a employment insurance policy based on a quote previously created by the\nLFI. The TPP will send the `QuoteId` that has been saved by the LFI, together with\nany additional data that is required to create the insurance policy. The\nLFI will then invoke their BAU process to create the insurance policy.\n\nAfter the policy initiation request has been sent the User will be redirected to\nthe LFI to complete the creation of the insurance policy.",
      "parameters": [
        {
          "$ref": "#/components/parameters/Authorization"
        },
        {
          "$ref": "#/components/parameters/x-customer-user-agent"
        },
        {
          "$ref": "#/components/parameters/x-fapi-auth-date"
        },
        {
          "$ref": "#/components/parameters/x-fapi-customer-ip-address"
        },
        {
          "$ref": "#/components/parameters/x-fapi-interaction-id"
        }
      ],
      "responses": {
        "201": {
          "description": "The request has succeeded and a new resource has been created as a result.",
          "headers": {
            "x-fapi-interaction-id": {
              "required": false,
              "description": "An RFC4122 UID used as a correlation ID.",
              "schema": {
                "type": "string"
              }
            }
          },
          "content": {
            "application/jwt": {
              "schema": {
                "type": "object",
                "properties": {
                  "iss": {
                    "type": "string",
                    "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.1](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.1)"
                  },
                  "exp": {
                    "type": "number",
                    "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.4](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.4)"
                  },
                  "nbf": {
                    "type": "number",
                    "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5)"
                  },
                  "aud": {
                    "type": "array",
                    "items": {
                      "type": "string"
                    },
                    "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.3](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.3)"
                  },
                  "iat": {
                    "type": "number",
                    "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.6](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.6)"
                  },
                  "message": {
                    "type": "object",
                    "properties": {
                      "Data": {
                        "$ref": "#/components/schemas/AEInsuranceInsurancePolicyResponseData1"
                      },
                      "Links": {
                        "$ref": "#/components/schemas/AECreateInsurancePolicyLinks1"
                      },
                      "Meta": {
                        "$ref": "#/components/schemas/Meta"
                      }
                    },
                    "required": [
                      "Data",
                      "Links",
                      "Meta"
                    ],
                    "additionalProperties": false
                  }
                },
                "required": [
                  "iss",
                  "exp",
                  "nbf",
                  "message"
                ],
                "additionalProperties": false
              }
            }
          }
        },
        "400": {
          "$ref": "#/components/responses/400Error"
        },
        "401": {
          "$ref": "#/components/responses/401Error"
        },
        "403": {
          "$ref": "#/components/responses/403Error"
        },
        "404": {
          "$ref": "#/components/responses/404Error"
        },
        "405": {
          "$ref": "#/components/responses/405Error"
        },
