{
  "type": "object",
  "properties": {
    "InsurancePolicyId": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEInsuranceResourceIdentifierType"
        }
      ],
      "description": "Unique identifier for a given insurance policy",
      "example": "d330c5bb-0889-4596-86bb-17cc9a4a17b5"
    },
    "PostIssuanceResponse": {
      "type": "object",
      "properties": {
        "ClaimsAllowed": {
          "type": "boolean",
          "description": "Indicates whether the LFI allows the TPP to handle customer claims processes after policy issuance."
        },
        "EndorsementsAllowed": {
          "type": "boolean",
          "description": "Indicates whether the LFI allows the TPP to handle policy endorsements after policy issuance."
        },
        "RenewalsAllowed": {
          "type": "boolean",
          "description": "Indicates whether the LFI allows the TPP to handle the policy renewal process."
        },
        "CancellationAllowed": {
          "type": "boolean",
          "description": "Indicates whether the LFI allows the TPP to handle the policy cancellation when requested by the customer."
        }
      },
      "required": [
        "ClaimsAllowed",
        "EndorsementsAllowed",
        "RenewalsAllowed",
        "CancellationAllowed"
      ],
      "description": "Defines whether the LFI allows or rejects the TPPs request for accountability over specific post-policy issuance activities.",
      "additionalProperties": false
    },
    "Documents": {
      "type": "array",
      "items": {
        "$ref": "#/components/schemas/AEDocumentProperties"
      },
      "minItems": 1,
      "description": "Policy documents to be issued to the Customer via the TPP."
    }
  },
  "additionalProperties": false
}

{
  "type": "string",
  "minLength": 1,
  "maxLength": 128,
  "description": "Unique identifier for a given insurance policy. \n\nA uuid v4 is recommended for consistency but not mandatory."
}

{
  "type": "object",
  "required": [
    "Type",
    "FileName",
    "ContentType",
    "Content",
    "HashType",
    "Hash"
  ],
  "properties": {
    "Type": {
      "type": "string",
      "description": "The type of document that has been provided.  For example, Policy Booklet, Terms & Conditions"
    },
    "FileName": {
      "type": "string",
      "description": "Original file name for operator reference (no paths). Should include  a suitable extension (e.g., policy.pdf, terms.pdf)."
    },
    "ContentType": {
      "type": "string",
      "enum": [
        "application/pdf",
        "image/jpeg",
        "image/png"
      ],
      "description": "Content (MIME) type of the document, using IANA-registered media types, and based on types supported in the Open Finance Framework."
    },
    "Content": {
      "type": "string",
      "format": "base64",
      "description": "Base64-encoded representation of the document content.  The encoded string must be generated from the raw file bytes and decoded by the LFI to restore the original file."
    },
    "HashType": {
      "type": "string",
      "enum": [
        "SHA256"
      ],
      "description": "Approach used to create checksum or hash of the file. SHA256 is supported."
    },
    "Hash": {
      "type": "string",
      "description": "Checksum of the original file bytes created using the method indicated by `HashType`. Required to enable integrity verification by comparing with the hash or checksum calculated on the decoded file."
    },
    "AdditionalInformation": {
      "type": "string",
      "maxLength": 1000,
      "description": "Optional free text notes providing context on the document."
    }
  },
  "additionalProperties": false
}

{
  "type": "object",
